#include "ksMidiFileEventCoordinator.h"
#include <array>
#include <cstring>
#include <iostream>
#include <stdexcept>
struct Resolver{ks::MidiFileEventTask::Kind fileMeta(uint8_t,uint8_t,uint32_t){return ks::MidiFileEventTask::Kind::Skip;}};
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(){try{using C=ks::MidiFileEventCoordinator;using D=C::StreamReadDomain;Resolver resolver;unsigned jobs=0,rejects=0,under=0,reads=0;for(auto kind:{C::Kind::Skip,C::Kind::Continue})for(auto domain:{D::Existing,D::MonoBootRomData,D(255)})for(auto start:{0u,0x38eu,0x38fu}){C c(kind,C::Input{start,0,0,0,domain});unsigned low=0;bool threw=false;for(unsigned i=0;!c.complete()&&i<64;++i){const auto cost=c.nextClocks();if(!cost){std::cerr<<"STALL kind="<<unsigned(kind)<<" domain="<<unsigned(domain)<<" start="<<std::hex<<start<<" component="<<unsigned(c.component())<<" request="<<unsigned(c.request())<<std::dec<<"\n";throw std::runtime_error("Domain stalled");}std::array<unsigned char,sizeof(C)>before{};std::memcpy(before.data(),&c,sizeof(C));unsigned callbacks=0;check(!c.advanceBefore(cost-1,[&](uint32_t,unsigned){++callbacks;return uint8_t(0);},[&](uint32_t,uint8_t,unsigned){++callbacks;},resolver)&&!callbacks&&!std::memcmp(before.data(),&c,sizeof(C)),"Underbudget domain mutation");++under;try{c.advanceBefore(cost,[&](uint32_t a,unsigned){++callbacks;++reads;if(a<0x38f)++low;return uint8_t(0);},[&](uint32_t,uint8_t,unsigned){++callbacks;},resolver);}catch(const std::logic_error&){check(!callbacks&&!std::memcmp(before.data(),&c,sizeof(C)),"Domain reject mutated state/resources");threw=true;++rejects;break;}if(kind==C::Kind::Continue&&domain==D::MonoBootRomData&&low)break;}if(domain==D::MonoBootRomData&&start<0x38f){check(!threw&&(kind==C::Kind::Continue||c.complete())&&low==1,"Mono stream positive");}else check(threw&&!low,"Existing/crossboundary low stream admitted");++jobs;}
// A low-ROM stream reaching the boundary must be checked for each VLQ byte.
for(auto start:{0x38bu,0x38cu,0x38du,0x38eu}){C c(C::Kind::Skip,C::Input{start,0,0,0,D::MonoBootRomData});unsigned seen=0;bool rejected=false;for(unsigned i=0;!c.complete()&&i<128;++i){const auto cost=c.nextClocks();std::array<unsigned char,sizeof(C)>before{};std::memcpy(before.data(),&c,sizeof(C));unsigned callbacks=0;try{c.advanceBefore(cost,[&](uint32_t a,unsigned){++callbacks;++seen;check(a<0x38f,"Boundary read escaped");return uint8_t(0x80);},[&](uint32_t,uint8_t,unsigned){++callbacks;},resolver);}catch(const std::logic_error&){check(!callbacks&&!std::memcmp(before.data(),&c,sizeof(C)),"Crossboundary reject mutated");rejected=true;++rejects;break;}}if(start==0x38b)check(!rejected&&c.complete()&&seen==4,"Fourbyte VLQ boundary positive");else check(rejected&&seen==0x38f-start,"Per-byte VLQ boundary guard");++jobs;}
std::cout<<"PASS FileStreamCapability jobs="<<jobs<<" rejects="<<rejects<<" underbudget="<<under<<" reads="<<reads<<" preflight_no_mutation=1 default_existing_backed_only=1\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
